module accu (
    input               clk,
    input               rst_n,
    input       [7:0]   data_in,
    input               valid_in,
    output  reg         valid_out,
    output  reg [9:0]   data_out
);

integer i;
reg [7:0] data_in_reg[0:3];
reg [1:0] counter;
reg [1:0] counter_next;
reg [9:0] data_out_next;
reg valid_out_next;
always@(posedge clk or negedge rst_n) begin
	if(!rst_n) begin
		counter <= 2'b0;
	end
	else begin
		counter <= counter_next;
	end
end
always@(*) begin
	case(counter)
		2'b00: begin
			if(valid_in) begin
				counter_next = 2'b01;
				data_in_reg[counter] = data_in;
			end
			else begin
				counter_next = 2'b00;
			end
		end
		2'b01: begin
			if(valid_in) begin
				counter_next = 2'b10;
				data_in_reg[counter] = data_in;
			end
			else begin
				counter_next = 2'b01;
			end
		end
		2'b10: begin
			if(valid_in) begin
				counter_next = 2'b11;
				data_in_reg[counter] = data_in;
			end
			else begin
				counter_next = 2'b10;
			end
		end
		2'b11: begin
			if(valid_in) begin
				counter_next = 2'b00;
				data_in_reg[counter] = data_in;
			end
			else begin
				counter_next = 2'b11;
			end
		end
	endcase
end
always@(*) begin
	if(counter == 2'b11 && valid_in) begin
		data_out_next = data_in_reg[0]+data_in_reg[1]+data_in_reg[2]+data_in_reg[3];
	end
	else begin
		data_out_next = 10'b0;
	end
end
always@(*) begin
	if(data_out_next != 10'b0) begin
		valid_out_next = 1'b1;
	end
	else begin
		valid_out_next = 1'b0;
	end
end
always@(posedge clk or negedge rst_n) begin
	if(!rst_n) begin
		data_out <= 10'b0;
	end
	else begin
		data_out <= data_out_next;
	end
end
always@(posedge clk or negedge rst_n) begin
	if(!rst_n) begin
		valid_out <= 1'b0;
	end
	else begin
		valid_out <= valid_out_next;
	end
end
endmodule
